"kind": "propose",
"summary": "The new revision's liveness probe timeout is too short, causing the app to be killed during startup. Increasing the timeout will allow the app to start properly.",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "The liveness probe's timeout of 1 second is too short for the app's startup process, which takes longer than the timeout allows.",
    "supporting": ["failure_onset_after_rollout", "killed_during_startup", "probe_kills", "probe_timeouts"],
    "contradicting": ["oom_killed_new_revision", "crashed_on_its_own"],
    "missing": ["container_memory", "memory_at_limit_before_kill", "evicted_for_node_memory", "oom_after_long_run"],
    "status": "supported"
  },
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "The app takes longer than the probe's timeout to start, leading to repeated failures.",
    "supporting": ["failure_onset_after_rollout", "killed_during_startup", "probe_kills"],
    "contradicting": ["oom_killed_new_revision", "crashed_on_its_own"],
    "missing": ["container_memory", "memory_at_limit_before_kill", "evicted_for_node_memory", "oom_after_long_run"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    },
    "readiness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "The liveness and readiness probes will have longer timeout periods, allowing the application to start and pass the probes before being restarted.",
  "rationale": "The logs show the app took over 5 seconds to start, but the liveness probe timeout is 1 second. Increasing the timeout to 5 seconds aligns with the observed startup time, preventing premature probe failures.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["failure_onset_after_rollout", "killed_during_startup", "probe_kills", "probe_timeouts"]
}
}
